--region init
function ActivityCakeShopBossMain:InitHandler()
    SetButtonAction(self.Btncheck, Bind(self, self.OnBtnBossDetailClickHandler))
    SetButtonAction(self.BtnList, Bind(self, self.OnBtnListClickHandler))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnHurtRewardClickHandler))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFightHandler))
    self.events[Constants.EventNames.CommonActivityBossHurtTipsChanged] = Events.AddListener(Constants.EventNames.CommonActivityBossHurtTipsChanged, Bind(self, self.RefreshRedPoint))
    ---@type ActivityCakeShopBossMainRankNode
    self._playerRankScr = CfUtils.GetLuaScr(self.WorldBossPlayerRankingsDialog, "Game.UI.ActivityCakeShopDialog.ActivityCakeShopBossMainRankNode")
end



function ActivityCakeShopBossMain:InitData()
    self._planVo = ActivityCakeUtils.GetActivityBossScheduleVo(1)
    self._questVo = ActivityCakeUtils.GetActivityBossLevelVo(self._planVo.range)

    self.requestSuccess = false
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseBoss,{ activityUuid = activityData.id },function(request,response)
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            self.serverData = responseData
            ActivityCakeUtils.GetActivityCakeMgr():SaveActivityBossData(self.serverData)
            self.requestSuccess = true
            self:OnBossHomeReqHandler()
        end
    end)

    while not self.requestSuccess do
        coroutine.yield()
    end
end
--endregion init

--region handler
function ActivityCakeShopBossMain:OnBtnListClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.ActivityCakeShopBossRankRewardDialog
    })
end

function ActivityCakeShopBossMain:OnBtnHurtRewardClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.ActivityCakeShopBossDamageBonusDialog
    })
end

function ActivityCakeShopBossMain:OnBtnFightHandler()
    local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            activityUuid = activityData.id,
            levelId = self._planVo.range
        }
    }, {
        { id = Constants.UITypeIds.ActivityCakeShopBossMain }
    })
end

function ActivityCakeShopBossMain:OnBtnBossDetailClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.ActivityCakeShopBossDetailsDialog, parameters = { planVo = self._planVo ,questVo = self._questVo }
    },{
        { id = Constants.UITypeIds.ActivityCakeShopBossMain }
    })
end

function ActivityCakeShopBossMain:OnBossHomeReqHandler()
    self:RefreshUI()
end
--endregion handler

--region private
function ActivityCakeShopBossMain:RefreshPlayerRank()
    self._playerRankScr:Refresh(self.serverData)
end

function ActivityCakeShopBossMain:RefreshUI()
    CfUtils.FillImage(self.Bg, self._planVo.modelId)

    self.lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self._planVo.range)
    for _, line in ipairs(self.lineUpInfo) do
        local ids = line.wave1NpcId
        for index, id in ipairs(ids) do
            local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
            if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss then
                local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
                CfUtils.FillText(self.TxtName, skinVo.name)
            end
        end
    end

    CfUtils.RefreshTopGoods({})

    self:RefreshPlayerRank()
    self:RefreshRedPoint()
end

function ActivityCakeShopBossMain:RefreshRedPoint()
    local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
    local hasRedPoint = homeDojo:GetBossTips() == 0
    CfUtils.SetActive(self.BtnReward.transform:Find("redPoint"), hasRedPoint)
end
--endregion private

